    iif(a - CAST(a AS INTEGER) < 0, (a - CAST(a AS INTEGER) + 1) * 536870913.0 - ((a - CAST(a AS INTEGER) + 1) * 536870913.0 - (a - CAST(a AS INTEGER) + 1)), a - CAST(a AS INTEGER)) AS m,
