    iif(d < sunr, max(0.0, min(1.0, (((sunr - d) * 536870913.0 - ((sunr - d) * 536870913.0 - (sunr - d))) / sunk) * 536870913.0 - ((((sunr - d) * 536870913.0 - ((sunr - d) * 536870913.0 - (sunr - d))) / sunk) * 536870913.0 - (((sunr - d) * 536870913.0 - ((sunr - d) * 536870913.0 - (sunr - d))) / sunk)))), NULL) AS edge
