    CASE WHEN kind = 2 THEN ((((floorr - zr) * 536870913.0 - ((floorr - zr) * 536870913.0 - (floorr - zr))) + (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - ((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line)))) * 536870913.0 - ((((floorr - zr) * 536870913.0 - ((floorr - zr) * 536870913.0 - (floorr - zr))) + (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - ((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line)))) * 536870913.0 - (((floorr - zr) * 536870913.0 - ((floorr - zr) * 536870913.0 - (floorr - zr))) + (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - (((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line) * 536870913.0 - ((0.55 * 536870913.0 - (0.55 * 536870913.0 - 0.55)) * line))))))
