    CASE WHEN kind = 2 THEN ((((floorb - zb) * 536870913.0 - ((floorb - zb) * 536870913.0 - (floorb - zb))) + (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - ((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line)))) * 536870913.0 - ((((floorb - zb) * 536870913.0 - ((floorb - zb) * 536870913.0 - (floorb - zb))) + (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - ((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line)))) * 536870913.0 - (((floorb - zb) * 536870913.0 - ((floorb - zb) * 536870913.0 - (floorb - zb))) + (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - (((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line) * 536870913.0 - ((0.75 * 536870913.0 - (0.75 * 536870913.0 - 0.75)) * line))))))
