    iif(r <= 0, 0, iif(r >= 1, 255, CAST(r * 255 + 0.5 AS INTEGER))),
    iif(g <= 0, 0, iif(g >= 1, 255, CAST(g * 255 + 0.5 AS INTEGER))),
    iif(b <= 0, 0, iif(b >= 1, 255, CAST(b * 255 + 0.5 AS INTEGER)))), sky), ''))
FROM p5;
